
-- Additive operational records. Existing immutable versions/chunks/history are untouched.
CREATE TABLE "KnowledgeSourceObject" ("versionId" TEXT PRIMARY KEY REFERENCES "KnowledgeDocumentVersion"(id) ON DELETE CASCADE, "objectKey" TEXT NOT NULL UNIQUE, backend TEXT NOT NULL);
CREATE TABLE "KnowledgeIngestion" ("versionId" TEXT PRIMARY KEY REFERENCES "KnowledgeDocumentVersion"(id) ON DELETE CASCADE, generation INTEGER NOT NULL DEFAULT 1, "requestId" TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'QUEUED', attempts INTEGER NOT NULL DEFAULT 0, retryable BOOLEAN NOT NULL DEFAULT true, "errorCategory" TEXT, "heartbeatAt" TIMESTAMP(3), "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "chunksTotal" INTEGER NOT NULL DEFAULT 0, "chunksEmbedded" INTEGER NOT NULL DEFAULT 0, "embeddingModel" TEXT, "lexicalReady" BOOLEAN NOT NULL DEFAULT false, "semanticReady" BOOLEAN NOT NULL DEFAULT false, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "KnowledgeIngestion_stage_updatedAt_idx" ON "KnowledgeIngestion"(stage,"updatedAt");
CREATE TABLE "KnowledgeIngestionAttempt" (id TEXT PRIMARY KEY,"versionId" TEXT NOT NULL REFERENCES "KnowledgeIngestion"("versionId") ON DELETE CASCADE,generation INTEGER NOT NULL,attempt INTEGER NOT NULL,"jobId" TEXT NOT NULL,"requestId" TEXT NOT NULL,stage TEXT NOT NULL,"errorCategory" TEXT,retryable BOOLEAN NOT NULL DEFAULT true,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),"completedAt" TIMESTAMP(3),"durationMs" INTEGER, UNIQUE("versionId",attempt));
CREATE TABLE "KnowledgeOutbox" (id TEXT PRIMARY KEY,"versionId" TEXT NOT NULL REFERENCES "KnowledgeIngestion"("versionId") ON DELETE CASCADE,generation INTEGER NOT NULL,"requestId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),"availableAt" TIMESTAMP(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),"dispatchedAt" TIMESTAMP(3),"claimToken" TEXT,"claimUntil" TIMESTAMP(3),attempts INTEGER NOT NULL DEFAULT 0,"errorCategory" TEXT,UNIQUE("versionId",generation));
CREATE INDEX "KnowledgeOutbox_dispatchedAt_availableAt_idx" ON "KnowledgeOutbox"("dispatchedAt","availableAt");
